def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse history into compact counts.
    opp_c = 0
    my_c = 0
    last_opp = history[-1][1]
    last_me = history[-1][0]
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    # Windowed opponent behavior.
    w = 12 if n >= 12 else n
    recent_opp_c = 0
    recent_opp_d = 0
    recent_me_d = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1
        if a == 'D':
            recent_me_d += 1

    # Endgame: last few rounds, exploit pure/near-pure cooperators.
    if n >= 95:
        if opp_d <= 2:
            return 'D'
        if opp_d <= max(3, n // 15):
            return 'D'
        if last_opp == 'C' and opp_d <= n // 4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Pure cooperator: exploit steadily but not from the very start,
    # keeping enough cooperation to prevent collapse before n=20.
    if opp_d == 0:
        if n < 12:
            return 'C'
        if n < 30:
            return 'D' if rng.random() < 0.20 else 'C'
        if n < 70:
            return 'D' if rng.random() < 0.45 else 'C'
        return 'D' if rng.random() < 0.80 else 'C'

    # Pure/sustained defector: defect hard.
    if opp_c == 0:
        return 'D'
    if recent_opp_d >= w - 1:
        return 'D'

    # Highly cooperative opponent: maintain cooperation, occasional probe,
    # then exploit near end.
    if opp_d <= max(1, n // 12):
        if last_opp == 'D':
            # Forgive a single late defection to avoid TFT-style mistakes.
            return 'D' if recent_opp_d >= 2 else 'C'
        if n >= 80:
            return 'D' if rng.random() < 0.30 else 'C'
        if n >= 40:
            return 'D' if rng.random() < 0.08 else 'C'
        if n >= 15:
            return 'D' if rng.random() < 0.04 else 'C'
        return 'C'

    # Mostly-defective opponent: punish, but probe for revival.
    if opp_d >= opp_c + 3 or recent_opp_d * 2 >= w:
        if last_opp == 'C' and recent_opp_c >= 2:
            if rng.random() < 0.35:
                return 'C'
        if recent_me_d >= w - 1 and last_opp == 'C':
            return 'C'
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Mixed regime: forgiving tit-for-tat with anti-death-spiral.
    if last_opp == 'D':
        # If mutual defection loop, break out with cooperation.
        if last_me == 'D' and recent_opp_d >= 3:
            if rng.random() < 0.70:
                return 'C'
        # If we've been very defection-heavy, occasionally reset.
        if my_d > opp_d + 3 and rng.random() < 0.35:
            return 'C'
        # Small chance to forgive a single opponent defection.
        if recent_opp_d <= 2 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if last_me == 'D':
        # If we've been exploiting, keep going a bit, but not endlessly.
        if my_d > opp_d + 2 and rng.random() < 0.55:
            return 'D'
        return 'C'

    # Mostly cooperate; small probe against moderately cooperative opponents.
    if rng.random() < 0.03:
        return 'D'
    return 'C'
